//Get List of Duplicate users
function getDuplicateValues(table, field) {
    var dupValues = [];
    var ga = new GlideAggregate(table);
    ga.addAggregate('COUNT', field);
    ga.addNotNullQuery(field);
    //ga.groupBy(field);
    ga.addHaving('COUNT', '>', 1);
    ga.setLimit(10);
    ga.query();
    while (ga.next()) {
        dupValues.push(ga[field].toString());
    }
    return dupValues;
}

var dupes = getDuplicateValues('sys_user', 'u_objectsid');
for (var i = 0; i < dupes.length; i++) {
    var userArr = [];
    var duplicates = new GlideRecord('sys_user');
    duplicates.addEncodedQuery('u_objectsid=' + dupes[i]);
    duplicates.orderBy('last_login_time');
    duplicates.query();

    while (duplicates.next()) {

        var dupUsers = new GlideRecord('sys_user');
        dupUsers.addQuery('u_objectsid', duplicates.u_objectsid);
        //dupUsers.addQuery('sys_id',"!=",duplicates.sys_id);
        dupUsers.query();

        gs.info('name: ' + dupUsers.name);

        if (dupUsers.getRowCount() > 1) {
            var loginDate1 = duplicates.last_login_time;
            var loginDate2 = dupUsers.last_login_time;

            if (loginDate1 < loginDate2) {
                gs.info("LoginDate1<LoginDate2 & LoginDate1: " + loginDate1 + " LoginDate2: " + loginDate2);
            } else {
                gs.info("LoginDate1>LoginDate2 & LoginDate1: " + loginDate1 + " LoginDate2: " + loginDate2);
            }
        }
        userArr.push(duplicates.sys_id + '');

        // var util = new ArrayUtil();
        // var dupUsers = util.unique(userArr);

        //var loginDate+[i] = duplicates.last_login_time; 
    }

}

//Find all references to user accounts
